mapper.update:
update "interviewworks_ticket".ticket ticket
set
    status = #{status},
    quantity = 0,
    cancelled_at = #{cancelled_at}
where orderno = #{orderno}
  and customer = #{customer}
  and status in ('PENDING_PAYMENT')

mapper.select:
select
    "session".id,
    "session".activity_id,
    "session"."date",
    "session"."time",
    "session".salesdate,
    "session".salestime
from "interviewworks_ticket"."session" "session"
where "session".id = #{session_id}
  and "session".activity_id = #{activity_id}
  and "session"."date" = #{date}
  and "session"."time" = #{time}
order by "session"."date" desc

